def fitlog(X,y,l2=1e-3):
    X=torch.tensor(X); y=torch.tensor(y,dtype=torch.float32); mu=X.mean(0); sd=X.std(0)+1e-6
    ww=torch.zeros(X.shape[1],requires_grad=True); bb=torch.zeros(1,requires_grad=True)
    opt=torch.optim.LBFGS([ww,bb],max_iter=300); pw=float((1-y).sum()/y.sum())
    def cl():
        opt.zero_grad(); zz=((X-mu)/sd)@ww+bb
        l=torch.nn.functional.binary_cross_entropy_with_logits(zz,y,pos_weight=torch.tensor(pw))+l2*(ww**2).sum(); l.backward(); return l
    opt.step(cl); return (ww/sd).detach(), float(bb-(mu/sd)@ww)
